INSERT INTO public.checklist_items (category, title, description, severity, sort_order, is_active, what_to_look_for, checklist_key) VALUES
('Agentic AI Security', 'Agent permissions scoped to the specific task', NULL, 'critical', 201, true, 'List every tool, API, and database table the agent has access to. For each one, confirm it is required for the agent''s actual job. Flag anything broader than necessary.', 'agent_permission_scope'),
('Agentic AI Security', 'Human approval required before high-impact actions', NULL, 'critical', 202, true, 'Identify every action the agent can take that is costly or irreversible — sending messages, spending money, modifying production data. Confirm each requires explicit human approval before executing, not just a log entry after.', 'agent_human_approval'),
('Agentic AI Security', 'Agent identity is distinct and auditable', NULL, 'high', 203, true, 'Check whether the agent uses its own scoped API credentials or borrows a human user''s or admin''s credentials. Confirm every agent action can be traced to the agent specifically, not a shared identity.', 'agent_identity'),
('Agentic AI Security', 'Tool descriptions and outputs are not blindly trusted', NULL, 'high', 204, true, 'Find every place the agent reads external content — web pages, emails, files, API responses. Confirm the code treats this content strictly as data, never as instructions to follow.', 'agent_tool_trust'),
('Agentic AI Security', 'Agent memory is validated before it influences future actions', NULL, 'high', 205, true, 'If the agent has persistent memory across sessions, confirm data written to that memory is sanitized the same way user input would be, before being trusted in a future action.', 'agent_memory_validation'),
('Agentic AI Security', 'Inter-agent communication is authenticated', NULL, 'medium', 206, true, 'If there is more than one agent or automated step passing instructions to another, confirm those messages are authenticated and validated, not implicitly trusted as internal.', 'agent_interagent_auth'),
('Agentic AI Security', 'A single agent failure can''t cascade into a full system failure', NULL, 'medium', 207, true, 'Check for limits on how many actions an agent can take consecutively, and for automatic pausing if outputs look abnormal.', 'agent_circuit_breaker'),
('Agentic AI Security', 'The user actually understands what the agent did, and why', NULL, 'low', 208, true, 'Review the approval UI shown to users before an agent acts. Confirm it shows a specific summary of the actual action, not a generic continue prompt.', 'agent_user_transparency');
